const SHARE_SVG='<svg width="24" height="24" viewBox="0 0 24 24" fill="none"><path d="M13.5 4.2V8.3C7.4 8.9 3.4 12.8 2.8 19.8C5 16.2 8.4 14.4 13.5 14.3V18.5L21.4 11.4Z" stroke="#333333" stroke-width="1.9" stroke-linejoin="round"/></svg>';
const SORT_SVG='<svg width="9.05" height="9.05" viewBox="0 0 9.05 9.05"><rect x="0.825" y="1.93" width="7.4" height=".54" rx=".27" fill="#333"/><rect x="1.725" y="4.23" width="5.6" height=".54" rx=".27" fill="#333"/><rect x="2.8" y="6.53" width="3.45" height=".54" rx=".27" fill="#333"/></svg>';
function textW(str,fs,fam,wt){cv.font=`${wt} ${fs*10}px ${FAM[fam]}`;return cv.measureText(str).width/10;}
function polishNote(t,id){const C=t.c;
  // 共 N 条评论: Medium 9.05 #333, as in the app (it was Regular 8.41 in the export)
  C.filter(o=>o.tx&&/^共 \d+ 条评论$/.test(txt(o))).forEach(o=>{const cy=o.y+o.h/2;o.tx[0][1]=9.05;o.tx[0][3]='Medium';o.tx[0][4]='#333333';o.h=11;o.y=cy-5.5;o.ar='W';});
  C.forEach(o=>{if(o.w>80&&o.h<4&&o._ay>550)o._skip=1;}); // the app hides the home indicator here
  const sh=C.find(o=>o.n==='ic/share-arrow');if(sh){sh.svgx=SHARE_SVG;sh.fit=1;}
  const so=C.find(o=>o.n==='ic/sort');if(so){so.svgx=SORT_SVG;so.svg='sort';so.c=null;so.fit=1;so.w=so.h=9.05;}
  const H=C.find(o=>o.n==='ic/heart'),St=C.find(o=>o.n==='ic/star'),Cm=C.find(o=>o.n==='ic/comment');if(!H||!St||!Cm)return;
  const pill=C.find(o=>o.t==='RE'&&o.x<20&&o.w>80&&o.w<110&&Math.abs(o.y+o.h/2-(H.y+H.h/2))<6);const cy=pill?pill.y+pill.h/2:H.y+H.h/2;
  const cnts=C.filter(o=>o.tx&&/^\d+$/.test(txt(o))&&Math.abs(o.y+o.h/2-cy)<5&&o.x>110).sort((a,b)=>a.x-b.x);
  let x=251.2,left=0;
  [[Cm,cnts[2]],[St,cnts[1]],[H,cnts[0]]].forEach(([ic,tx])=>{const sp=NOTE_IC[ic.n];const bw=sp.vis/sp.w;ic.w=bw;ic.h=bw*sp.ar;ic.y=cy-ic.h/2;ic.svgx=sp.svg;ic.fit=1;
    if(tx){tx.tx[0][1]=8.9;tx.tx[0][2]='Inter';tx.tx[0][3]='Medium';tx.tx[0][4]='#222222';const tw=textW(txt(tx),8.9,'Inter',500);tx.w=tw;tx.h=10.8;tx.ar='W';tx.x=x-tw;tx.y=cy-5.4;x=tx.x-3.9;}
    ic.x=x-bw*(sp.l+sp.w);left=ic.x+bw*sp.l;x=left-12.9;});
  if(pill)pill.w=left-10.3-pill.x;
  if(id==='s02'||id==='s06')moreComments(t,id);}
