  $('#tacts').innerHTML=ACTS.map((a,i)=>`<button class="${a.pri?'pri':''}${a.sel?' sel':''}" data-a="${i}">${a.label}</button>`).join('');$('#tctl').innerHTML=step<steps.length?'<button>再来一遍</button>':'';
