document.addEventListener('click',e=>{const sb=e.target.closest('.stepbtn,[data-si]');if(sb){const m=$('.msheet');m&&m.remove();const p=sb.dataset.p,i=+(sb.dataset.i??sb.dataset.si);if(!(p===path&&i===step))jump(p,i);return;}const b=e.target.closest('.pathbtn');if(b){const inSheet=!!b.closest('.msheet');const m=$('.msheet');m&&m.remove();if(inSheet||b.dataset.p!==path)start(b.dataset.p);}});
