/* ---------- D: edge cases (Figma v9-09 边界与异常) ---------- */
/* D12 the 大家晒的 entry by how many people shared: 0 = one light line, 1–2 = a single row, 3+ = the photo list */
const TIERS=[['0 人','没人晒过：只留一行「有经验？分享一下 ›」，给第一位分享的人留个位置'],['1–2 人','1–2 人晒过：收成一行，头像加人数，不硬凑图片'],['3 人以上','3 人以上：展开图片列表（路径 A 里看到的就是这种）']];
function s02D(tier=0,o={}){const t=clone('s02');walk(t,()=>{});
  const ttl=t.c.find(x=>x.tx&&/^大家晒的 \d+$/.test(txt(x))),more=t.c.find(x=>x.tx&&txt(x)==='查看 ›'&&x._ay<150);
  const thumbs=t.c.filter(x=>x.t==='RE'&&Math.abs(x._ay-152.64)<.5&&x.h>44&&x.h<45),plus=t.c.find(x=>x.tx&&txt(x)==='+81');
  if(tier<2){thumbs.forEach(x=>x._skip=1);if(plus)plus._skip=1;const bix=t.c.findIndex(x=>x.w>=259&&x._ay>500);
    t.c.forEach((x,i)=>{if(i<bix&&x._ay>=200)x.y-=50.31;});
    const right=more.x+more.w;
    if(tier===0){ttl.ar='W';setText(ttl,'有经验？');ttl.tx[0][4]='#999999';setText(more,'分享一下 ›');more.tx[0][4]='#ff2442';more.w=textW('分享一下 ›',8.41,'Noto Sans SC',400);more.x=right-more.w;more.ar='W';}
    else{setText(ttl,'2 人晒过');ttl.x=45.17;ttl.ar='W';const av=(x,img)=>({t:'EL',x,y:134.01,w:14.8,h:14.8,n:'av',f:[{img}],r:999,s:['#ffffff',1.3,'I']});t.c.splice(t.c.indexOf(ttl),0,av(10.38,'i13'),av(19.95,'i14'));}}
  go(0,TIERS[tier][1],[...TIERS.map(([k],i)=>({label:k,sel:i===tier,fn:()=>{if(i!==tier)s02D(i,{anim:'fade'});}}))]);
  render(t,noteScroll(t,o));noteBack(t);walk(t,()=>{});
  const row=[ttl,more];const y=Math.min(...row.map(x=>x._ay))-6;
  if(tier===0)hotRect(0,y,260,24,()=>note('会打开晒图的输入框，和路径 C 一样'),'分享一下');
  else if(tier===1)hotRect(0,y,260,24,()=>note('会打开「大家晒的」，这里只有 2 条'),'2 人晒过，查看');
  else hotRect(8,132,244,68,()=>note('会打开「大家晒的」，和路径 A 一样'),'打开大家晒的');}

